#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn basic() {
        assert_eq!(longest_word("the quick brownish fox"), "brownish");
    }

    #[test]
    fn tie_returns_first() {
        assert_eq!(longest_word("ab cd ef"), "ab");
    }

    #[test]
    fn empty_and_blank() {
        assert_eq!(longest_word(""), "");
        assert_eq!(longest_word("   \t\n"), "");
    }

    #[test]
    fn borrows_from_input() {
        let s = String::from("  hello   wonderful world ");
        let w = longest_word(&s);
        assert_eq!(w, "wonderful");
        let start = w.as_ptr() as usize - s.as_ptr() as usize;
        assert_eq!(&s[start..start + w.len()], "wonderful");
    }

    #[test]
    fn single_word() {
        assert_eq!(longest_word("rust"), "rust");
    }
}
